#!/usr/bin/env python3
"""Build the English handbook from bundled catalogs and localized previews."""
import sys
sys.dont_write_bytecode=True
import html,json
from pathlib import Path
B=Path(__file__).resolve().parents[1]
K=B/'assets/packaging/src'
E=html.escape
base=json.loads((K/'components.json').read_text(encoding='utf-8'))
variants=json.loads((K/'variants.json').read_text(encoding='utf-8'))

def preview(id,hero=False):
    return f'<img class="specimen-preview" loading="{"eager" if hero else "lazy"}" width="1920" height="1080" data-specimen="{id}" src="../assets/packaging/previews/en-US/{id}.jpg" alt="{E(id)} layout preview">'

def card(row,index):
    id=row['id'];motion=row.get('motion','Reveals follow the narration. Hold each thought long enough to read.')
    inputs=row.get('inputs','Use the data and cue fields in the renderer contract.')
    return f'''<article class="specimen" id="sample-{id}"><div class="specimen-top"><span>{index:02d} / {id.upper()}</span><span>EDITABLE SOURCE</span></div>{preview(id)}<div class="specimen-copy"><h3>{E(row['name'])}</h3><p>{E(row['purpose'])}</p><p class="motion">{E(motion)}</p><details><summary>Inputs and reuse</summary><p>{E(inputs)}</p><p>Replace the content and footage, then time the reveals to the narration. Eight seconds is a sample length, not a production rule.</p><p><a href="../assets/packaging/src/{'components.json' if row in base else 'variants.json'}">View the inputs</a></p></details></div></article>'''

hero=base[0]
base_cards=''.join(card(row,i+1) for i,row in enumerate(base) if not row['id'].startswith('map') and row['id']!='hero')
map_cards=''.join(f'<article class="map-study"><div class="map-frame">{preview(row["id"])}</div><div class="map-copy"><h3>{E(row["name"])}</h3><p>{E(row["purpose"])}</p><p class="muted">{E(row["motion"])}</p></div></article>' for row in base if row['id'].startswith('map'))
variant_cards=''.join(card(row,i+1) for i,row in enumerate(variants))
page='''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FEICAI · Visual Handbook</title><link rel="stylesheet" href="../assets/packaging/handbook.css"></head><body><main>
<div class="wrap"><header class="masthead"><b>FEICAI</b><span>EXPLAINERS / VISUAL HANDBOOK</span></header>
<div class="cover"><div><span class="smallcaps">A SHARED VISUAL LANGUAGE</span><h1>Ideas,<br>made visible.</h1><p class="lead">A visual system for explaining how people think, choose, and change. Real footage carries the situation. Graphics make the relationships clear.</p><nav><a href="#type">Typography</a><a href="#components">Components</a><a href="#maps">Maps</a><a href="#shared">Variants</a><a href="#review">Review</a></nav><div class="language-picker" role="group" aria-label="Example language"><button type="button" data-language="en-US" aria-pressed="true">English examples</button><button type="button" data-language="zh-CN" aria-pressed="false">Chinese examples</button></div><p class="guide-note">The guide stays in English. Switch the language of the layout previews. Motion timing remains in the component source.</p></div><div class="cover-film">__HERO__<div class="folio"><span>01 / EDITORIAL COLLAGE</span><span>Subject first. Question next.</span></div></div></div>
<div class="intro"><p>One series can tell many kinds of stories. Keep the typography, color relationships, alignment, and sense of depth consistent while letting each topic choose its own form.</p><p>These are working components, not a sequence every film must follow. Use a graphic when it adds understanding, then let the story move on.</p></div></div>
<section id="type"><div class="wrap"><div class="section-top"><div><span class="index">01 / TYPOGRAPHY & COLOR</span><h2>Give every word<br>a clear role.</h2></div><p>English and Chinese share the same design system, with different fonts and line breaks. Keep the hierarchy clear without forcing one language into the other's measure.</p></div><div class="type-layout"><div class="type-art"><div class="display">Look closely.<br><em>Think again.</em></div><div class="latin">EVIDENCE / CONTEXT / JUDGMENT</div></div><div class="type-roles"><div class="type-role"><strong>Display</strong><p>Source Serif 4 for English. Noto Serif SC for Chinese. Use a few meaningful words as the visual anchor.</p></div><div class="type-role"><strong>Explanation</strong><p>Inter for English. Noto Sans SC for Chinese. Keep supporting copy next to the image or relationship it explains.</p></div><div class="type-role"><strong>Numbers</strong><p>Barlow Condensed for dates, counts, and chapter numbers. Make the unit and meaning clear.</p></div><div class="type-role"><strong>Captions</strong><p>Break English at phrase boundaries. Keep captions to two readable lines, with timing taken from the recording in that language.</p></div></div></div><div class="palettes"><div class="palette ink"><h3>Ink & gold</h3><p>Questions, concepts, and judgments. Deep photographic shadows and warm points of emphasis.</p></div><div class="palette ruby"><h3>Wine & jade</h3><p>Conflict and comparison. Color separates ideas without automatically declaring a winner.</p></div><div class="palette parchment"><h3>Paper & terrain</h3><p>Evidence, history, and maps. Give land, routes, places, and dates distinct visual roles.</p></div></div></div></section>
<section class="dark" id="components"><div class="wrap"><div class="section-top"><div><span class="index">02 / BASE DESIGNS</span><h2>Make the material<br>part of the explanation.</h2></div><p>Start with the missing piece: a subject, a distinction, a relationship, a sequence, or evidence. Replace the sample content and set the timing for the actual script.</p></div><div class="specimens">__BASE__</div></div></section>
<section class="wine" id="maps"><div class="wrap"><div class="section-top"><div><span class="index">03 / HISTORY & GEOGRAPHY</span><h2>Every story<br>happens somewhere.</h2></div><p>Use geography to establish place, explain distance, trace a route, or compare an extent. All layers share a coordinate system.</p></div>__MAPS__<div class="map-rules"><div><h3>Build the setting</h3><p>Show the land, rivers, and places the explanation needs. Add terrain only when it affects the story.</p></div><div><h3>Name the period</h3><p>Separate historical and modern names. Distinguish borders, administrative areas, influence, and control.</p></div><div><h3>Keep the scale</h3><p>Use matching projections and viewports for comparisons. Mark illustrative routes and uncertain boundaries honestly.</p></div></div></div></section>
<section class="dark" id="shared"><div class="wrap"><div class="section-top"><div><span class="index">04 / SHARED PRODUCTION COMPONENTS · 1.2.0</span><h2>One renderer.<br>Different stories.</h2></div><p>These variants use the same source that builds a film. Content, footage, coordinates, and cue times are inputs; layout and reveal behavior belong to the library.</p></div><div class="library-principles"><div><h3>Keep the system</h3><p>Reuse type roles, spacing, baselines, line geometry, and motion dependencies.</p></div><div><h3>Change the content</h3><p>Choose the variant for the explanation. Replace its material and time it to the narration.</p></div><div><h3>Test extensions</h3><p>Try a new variant with another topic and render it before adding it to the shared library.</p></div></div><div class="specimens">__VARIANTS__</div></div></section>
<section id="review"><div class="wrap"><div class="section-top"><div><span class="index">05 / LAYOUT, MOTION & REVIEW</span><h2>The details<br>carry the quality.</h2></div><p>Settle the composition before animating it. Then watch how it changes over time, with the real narration and score.</p></div><div class="standards-grid"><article class="standard"><h3>Layout</h3><p>Align related objects, balance image and text, and center conclusions on the group they summarize. Keep lines level and connectors clear of labels.</p></article><article class="standard"><h3>Purpose</h3><p>A component should add understanding. Omit redundant labels, decorative diagrams, and graphics that reveal the conclusion too early.</p></article><article class="standard"><h3>Language</h3><p>Keep words together and break at meaningful phrases. Avoid tiny type, stranded punctuation, and a lone word on the last line.</p></article><article class="standard"><h3>Footage</h3><p>Grade shots consistently. Use each original moving shot once in a production film, including blurred backgrounds and insets. Exclude smoking shots.</p></article></div><div class="order-rail"><div class="order-step"><b>01</b><h3>Subject</h3><p>Establish what viewers are looking at.</p></div><div class="order-step"><b>02</b><h3>Evidence</h3><p>Introduce the material needed to understand it.</p></div><div class="order-step"><b>03</b><h3>Relationship</h3><p>Connect elements after both sides exist.</p></div><div class="order-step"><b>04</b><h3>Conclusion</h3><p>Reveal the point when the explanation reaches it.</p></div></div><table class="check-table"><thead><tr><th>Check</th><th>What to look for</th></tr></thead><tbody><tr><td>Entrance</td><td>The subject is clear, the first words are intact, and a reveal does not arrive before its meaning.</td></tr><tr><td>Hold</td><td>Copy is readable. Group centers, labels, and line endpoints stay stable.</td></tr><tr><td>Transition</td><td>Watch the moving state as well as the start and end. Avoid clipping, flashes, and abrupt audio joins.</td></tr><tr><td>Export</td><td>Watch and listen to the actual MP4. A screenshot, transcript, or numeric check cannot establish the whole experience.</td></tr></tbody></table><div class="voice-note"><h3>A consistent narrator, a responsive performance</h3><p>Use the approved D reference and body-v1 settings. Design emphasis, pace, pauses, and emotion for each story. English and Chinese use the same voice reference, with separate language settings and pronunciation review.</p><p>Check first and last syllables, names, voice drift, natural phrasing, and music balance. The reference transcript stays in its recorded language.</p><p><a href="voice.md">Voice guide</a> · <a href="language.md">Language support</a> · <a href="studio.md">Lazy Studio review</a></p></div></div></section>
<footer class="wrap footer"><span>FEICAI · Explainers and video essays<br>A shared baseline, refined through real projects.</span><div class="links"><a href="packaging.md">Use the library</a><a href="../assets/packaging/src/renderer-contract.json">Renderer contract</a><a href="../assets/packaging/src/tokens.json">Design tokens</a><a href="assets.md">Asset credits</a></div></footer>
</main><script>
const specimens=[...document.querySelectorAll('img[data-specimen]')];
const buttons=[...document.querySelectorAll('button[data-language]')];
for(const button of buttons)button.addEventListener('click',()=>{const locale=button.dataset.language;for(const b of buttons)b.setAttribute('aria-pressed',String(b===button));for(const img of specimens)img.src=`../assets/packaging/previews/${locale}/${img.dataset.specimen}.jpg`;});
</script></body></html>'''
page=page.replace('__HERO__',preview('hero',True)).replace('__BASE__',base_cards).replace('__MAPS__',map_cards).replace('__VARIANTS__',variant_cards)
(B/'references/visual-handbook.html').write_text(page,encoding='utf-8')
print('Built English visual handbook with English and Chinese specimens.')
